<?php
declare(strict_types=1);
namespace SimpleMSPDoc\Modules\Integrations\Action1;
use SimpleMSPDoc\Core\{Actor,AccessPolicy,Database,HttpException};
use SimpleMSPDoc\Modules\Audit\AuditService;
use SimpleMSPDoc\Modules\Assets\{AssetService,TemplateService};
use SimpleMSPDoc\Modules\Organizations\OrganizationService;
final class Action1Service
{
 private Action1Client $client;
 private const FIELDS=['name'=>'Action1 device name','OS'=>'Operating system','address'=>'IP address','external_address'=>'External IP address','platform'=>'Platform','agent_version'=>'Action1 agent version','agent_install_date'=>'Agent installed','last_seen'=>'Last seen in Action1','status'=>'Action1 status','subscription_status'=>'Subscription status','user'=>'Last reported user','missing_critical_updates'=>'Missing critical updates','missing_other_updates'=>'Missing other updates','serial'=>'Serial number','manufacturer'=>'Manufacturer','RAM'=>'RAM','disk'=>'Storage','CPU_name'=>'Processor','CPU_size'=>'Processor specifications','MAC'=>'MAC address','comment'=>'Action1 notes'];
 public function __construct(private Database $db,private AuditService $audit,private SecretBox $box,?Transport $transport=null){$this->client=new Action1Client($db,$box,$transport??new CurlTransport());}
 private function admin(Actor $a): void {(new AccessPolicy($this->db))->admin($a);}
 private function locked(Actor $a,callable $fn): mixed {
  $this->admin($a);$name='mspdoc:action1:'.substr(hash('sha256',(string)$this->db->run('SELECT DATABASE()')->fetchColumn()),0,40);if((int)$this->db->run('SELECT GET_LOCK(?,0)',[$name])->fetchColumn()!==1)throw new Action1Error('Another Action1 operation is running. Try again shortly.',409);
  try{return $fn();}finally{$this->db->run('SELECT RELEASE_LOCK(?)',[$name]);}
 }
 public function state(Actor $a): array {$this->admin($a);$s=$this->db->one('SELECT enabled,region,credentials IS NOT NULL AS configured,next_request_at,catalog_complete,catalog_generation,last_error FROM action1_settings WHERE id=1');return ['settings'=>$s,'organizations'=>$this->db->all('SELECT external_id,name FROM action1_organizations WHERE generation=? ORDER BY name',[$s['catalog_generation']]),'mappings'=>$this->db->all('SELECT m.*,o.name AS local_name,r.name AS remote_name FROM action1_mappings m JOIN organizations o ON o.id=m.organization_id LEFT JOIN action1_organizations r ON r.external_id=m.external_organization_id ORDER BY o.name')];}
 public function saveSettings(Actor $a,array $input): void {$this->locked($a,function()use($a,$input){$s=$this->db->one('SELECT * FROM action1_settings WHERE id=1');$region=(string)($input['region']??'us');if(!isset(Action1Client::ORIGINS[$region]))throw new HttpException(422,'Choose a supported Action1 region.');$old=$s['credentials']?$this->box->open($s['credentials'],'credentials'):[];$id=trim((string)($input['client_id']??''));$secret=(string)($input['client_secret']??'');if($id==='')$id=$old['client_id']??'';if($secret==='')$secret=$old['client_secret']??'';
  if(strlen($id)>512||strlen($secret)>4096||preg_match('/[\r\n]/',$id.$secret))throw new HttpException(422,'Invalid API credentials.');if(!empty($input['enabled'])&&($id===''||$secret===''))throw new HttpException(422,'Enter the Action1 client ID and client secret.');$changed=$region!==$s['region']||$id!==($old['client_id']??'');if($changed&&$old!==[]&&(string)($input['client_secret']??'')==='')throw new HttpException(422,'Enter the client secret again when changing the region or client ID.');if($changed&&$this->db->one('SELECT id FROM action1_mappings LIMIT 1'))throw new HttpException(409,'This add-on is mapped to an Action1 account. Changing its region or client ID would risk mixing tenants. Rotate only the secret for this client ID.');
  $credentialChange=$changed||$secret!==($old['client_secret']??'');$cipher=$id!==''&&$secret!==''?$this->box->seal(['client_id'=>$id,'client_secret'=>$secret],'credentials'):null;$this->db->run('UPDATE action1_settings SET enabled=?,region=?,credentials=?,last_error=NULL WHERE id=1',[!empty($input['enabled'])?1:0,$region,$cipher]);if($credentialChange){$this->db->run('UPDATE action1_settings SET token_cipher=NULL,token_expires=0 WHERE id=1');if($changed){$this->db->run('DELETE FROM action1_organizations');$this->db->run('UPDATE action1_settings SET catalog_complete=0,catalog_offset=NULL WHERE id=1');}}$this->audit->record($a,'integration.configured','action1',null,null);
 });}
 public function test(Actor $a): array {return $this->locked($a,function()use($a){$page=$this->client->organizations();$this->db->run('UPDATE action1_settings SET last_error=NULL WHERE id=1');$this->audit->record($a,'integration.tested','action1',null,null);return ['more'=>false,'count'=>count($page['items']),'message'=>'Connection successful. The API can list organizations.'];});}
 public function discoverStart(Actor $a): array {return $this->locked($a,function(){ $this->enabled();$this->db->run('UPDATE action1_settings SET catalog_offset=0,catalog_complete=0,catalog_generation=catalog_generation+1,last_error=NULL WHERE id=1');return ['more'=>true,'message'=>'Loading Action1 organizations.'];});}
 public function discoverStep(Actor $a): array {return $this->locked($a,function(){ $s=$this->db->one('SELECT catalog_offset,catalog_generation FROM action1_settings WHERE id=1');if($s['catalog_offset']===null)return ['more'=>false,'message'=>'Organization list is complete.'];try{$page=$this->client->organizations((int)$s['catalog_offset']);$rows=[];$ids=[];foreach($page['items'] as $item){if(!is_array($item)||!Action1Client::validId($item['id']??null)||!is_string($item['name']??null)||trim($item['name'])==='')throw new Action1Error('Action1 returned an invalid organization.');$id=(string)$item['id'];if(isset($ids[$id]))throw new Action1Error('Action1 returned duplicate organization IDs.');$ids[$id]=true;$rows[]=[$id,mb_substr($item['name'],0,190),$s['catalog_generation']];}
  $this->db->transaction(function()use($rows,$page){foreach($rows as $row)$this->db->run('INSERT INTO action1_organizations(external_id,name,generation) VALUES (?,?,?) ON DUPLICATE KEY UPDATE name=VALUES(name),generation=VALUES(generation)',$row);$this->db->run('UPDATE action1_settings SET catalog_offset=?,catalog_complete=?,last_error=NULL WHERE id=1',[$page['next'],$page['next']===null?1:0]);});return ['more'=>$page['next']!==null,'message'=>$page['next']===null?'Organization list loaded. Map organizations below.':'Loading the next organization page.'];
  }catch(Action1Error $e){if($e->status!==429)$this->db->run('UPDATE action1_settings SET last_error=? WHERE id=1',[$e->getMessage()]);throw $e;}
 });}
 private function enabled(): void {if(!$this->db->one('SELECT id FROM action1_settings WHERE id=1 AND enabled=1 AND credentials IS NOT NULL'))throw new HttpException(422,'Enable Action1 and save API credentials first.');}
 public function map(Actor $a,string $external,int $org,bool $active): int {return $this->locked($a,function()use($a,$external,$org,$active){$this->enabled();(new OrganizationService($this->db,$this->audit))->get($a,$org);$existing=$this->db->one('SELECT * FROM action1_mappings WHERE external_organization_id=?',[$external]);if(!$existing){$s=$this->db->one('SELECT catalog_complete,catalog_generation FROM action1_settings WHERE id=1');if(!$s['catalog_complete']||!$this->db->one('SELECT external_id FROM action1_organizations WHERE external_id=? AND generation=?',[$external,$s['catalog_generation']]))throw new HttpException(422,'Load organizations and select one from the current list first.');}
  return $this->db->transaction(function()use($a,$external,$org,$active,$existing){if($existing){if((int)$existing['organization_id']!==$org&&$this->db->one('SELECT record_id FROM external_records WHERE connection_id=? LIMIT 1',[$existing['connection_id']]))throw new HttpException(409,'A mapping with imported devices cannot move to another organization.');$this->db->run('UPDATE action1_mappings SET organization_id=?,active=?,status=?,sync_offset=0,last_error=NULL WHERE id=?',[$org,$active?1:0,'idle',$existing['id']]);$this->db->run('UPDATE integration_connections SET organization_id=?,status=? WHERE id=?',[$org,$active?'enabled':'disabled',$existing['connection_id']]);$id=(int)$existing['id'];}else{$this->db->run("INSERT INTO integration_connections(organization_id,provider,status) VALUES (?,'action1',?)",[$org,$active?'enabled':'disabled']);$connection=(int)$this->db->connection()->lastInsertId();$this->db->run('INSERT INTO action1_mappings(external_organization_id,organization_id,connection_id,active) VALUES (?,?,?,?)',[$external,$org,$connection,$active?1:0]);$id=(int)$this->db->connection()->lastInsertId();}$this->audit->record($a,'integration.mapped','action1',$id,$org);return $id;});
 });}
 private function mapping(Actor $a,int $id): array {$this->enabled();$m=$this->db->one('SELECT * FROM action1_mappings WHERE id=? AND active=1',[$id]);if(!$m)throw new HttpException(404,'Active Action1 mapping not found.');(new OrganizationService($this->db,$this->audit))->get($a,(int)$m['organization_id']);return $m;}
 public function startSync(Actor $a,int $id): array {return $this->locked($a,function()use($a,$id){$m=$this->mapping($a,$id);$this->db->run("UPDATE action1_mappings SET sync_offset=0,status='running',processed_count=0,skipped_count=0,last_error=NULL WHERE id=?",[$id]);$this->audit->record($a,'integration.sync_started','action1',$id,(int)$m['organization_id']);return ['more'=>true,'message'=>'Sync started. Keep this page open.'];});}
 private function template(Actor $a): array {
  $s=$this->db->one('SELECT template_id,field_map FROM action1_settings WHERE id=1 FOR UPDATE');$templates=new TemplateService($this->db,$this->audit);
  if($s['template_id']){$id=(int)$s['template_id'];$this->db->one('SELECT id FROM asset_types WHERE id=? FOR UPDATE',[$id]);$map=json_decode($s['field_map'],true,32,JSON_THROW_ON_ERROR);foreach(self::FIELDS as $key=>$label)if(!isset($map[$key])){$templates->addField($a,$id,['name'=>$label,'type'=>'text']);$all=$templates->get($id)['fields'];$map[$key]=(int)end($all)['id'];}}
  else{$name='Action1 managed endpoint';$suffix=1;while($this->db->one('SELECT id FROM asset_types WHERE name=?',[$name]))$name='Action1 managed endpoint '.(++$suffix);$id=$templates->create($a,['name'=>$name,'description'=>'Fields supplied by the optional Action1 add-on. Manual details, notes and additional fields are preserved.','fields'=>array_map(fn($name)=>['name'=>$name,'type'=>'text'],array_values(self::FIELDS))]);$map=array_combine(array_keys(self::FIELDS),array_column($templates->get($id)['fields'],'id'));}
  $this->db->run('UPDATE action1_settings SET template_id=?,field_map=? WHERE id=1',[$id,json_encode($map,JSON_THROW_ON_ERROR)]);return ['id'=>$id,'fields'=>$map];
 }

 private function cell(mixed $value): ?string {if($value===null)return null;if(is_array($value)){if(!array_is_list($value)||count($value)>50)throw new Action1Error('Action1 returned an unsupported device field.');foreach($value as $v)if(!is_scalar($v))throw new Action1Error('Action1 returned an unsupported device field.');$value=implode(', ',array_map('strval',$value));}if(!is_scalar($value))throw new Action1Error('Action1 returned an unsupported device field.');return mb_substr((string)$value,0,1000);}
 public function syncStep(Actor $a,int $id): array {return $this->locked($a,function()use($a,$id){$m=$this->mapping($a,$id);if(!in_array($m['status'],['running','error'],true))throw new HttpException(409,'Start a sync before requesting a batch.');try{
  $page=$this->client->endpoints($m['external_organization_id'],(int)$m['sync_offset']);$normalized=[];$ids=[];foreach($page['items'] as $item){if(!is_array($item)||!Action1Client::validId($item['id']??null)||!is_string($item['name']??null)||trim($item['name'])==='')throw new Action1Error('Action1 returned an invalid device. The batch was not imported.');$external=(string)$item['id'];if(isset($ids[$external]))throw new Action1Error('Action1 returned duplicate device IDs.');$ids[$external]=true;$values=[];if(isset($item['missing_updates'])&&is_array($item['missing_updates']))foreach(['critical'=>'missing_critical_updates','other'=>'missing_other_updates'] as $key=>$target)if(array_key_exists($key,$item['missing_updates']))$item[$target]=$item['missing_updates'][$key];
   if(is_array($item['OS']??null)&&!array_is_list($item['OS']))$item['OS']=implode(' ',array_filter([$this->cell($item['OS']['name']??null),$this->cell($item['OS']['version']??null)],fn($v)=>$v!==null));
   foreach(self::FIELDS as $key=>$label)if(array_key_exists($key,$item))$values[$key]=$this->cell($item[$key]);$normalized[]=['id'=>$external,'name'=>mb_substr($item['name'],0,190),'values'=>$values];}
  $result=$this->db->transaction(function()use($a,$m,$page,$normalized,$id){$template=$this->template($a);$organization=$this->db->one('SELECT deleted_at FROM organizations WHERE id=? FOR UPDATE',[$m['organization_id']]);if(!$organization||$organization['deleted_at']!==null)throw new Action1Error('The mapped organization was archived. Restore it or disable this mapping.',409);$active=array_map('intval',array_column($this->db->all('SELECT id FROM asset_fields WHERE asset_type_id=? AND archived=0',[$template['id']]),'id'));$service=new AssetService($this->db,$this->audit);$processed=0;$skipped=0;
   foreach($normalized as $device){$link=$this->db->one('SELECT record_id FROM external_records WHERE connection_id=? AND external_id=?',[$m['connection_id'],$device['id']]);$old=null;if($link){$raw=$this->db->one('SELECT * FROM records WHERE id=? FOR UPDATE',[$link['record_id']]);if(!$raw||(int)$raw['organization_id']!==(int)$m['organization_id']||$raw['type']!=='asset')throw new Action1Error('An imported device mapping needs administrator attention.');if($raw['deleted_at']!==null){$skipped++;continue;}$old=\SimpleMSPDoc\Core\RecordRepository::decode($raw);(new AccessPolicy($this->db))->require($a,'write',new \SimpleMSPDoc\Core\RecordScope((int)$raw['organization_id'],$raw['visibility']));if((int)$old['payload']['template_id']!==$template['id'])throw new Action1Error('An imported device has an incompatible configuration template.');}
    $values=$old['payload']['values']??[];foreach($device['values'] as $key=>$value){$field=(int)$template['fields'][$key];if(in_array($field,$active,true))$values[$field]=$value;}$payload=$old['payload']??['template_id'=>$template['id'],'notes'=>''];$payload['values']=$values;$input=['title'=>$old['title']??$device['name'],'visibility'=>$old['visibility']??'internal','category'=>$old['category']??'Action1','tags'=>$old['tags']??[],'payload'=>$payload];if($old){$record=(int)$old['id'];$service->update($a,$record,$input);}else{$record=$service->create($a,(int)$m['organization_id'],$input);$this->db->run('INSERT INTO external_records(connection_id,external_id,record_id,managed_fields) VALUES (?,?,?,?)',[$m['connection_id'],$device['id'],$record,json_encode(array_values($template['fields']),JSON_THROW_ON_ERROR)]);}$reported=[];foreach($device['values'] as $source=>$value){$key=\SimpleMSPDoc\Modules\Assets\ConfigurationDetails::fieldKey(['name'=>self::FIELDS[$source]]);if(isset(\SimpleMSPDoc\Modules\Assets\ConfigurationDetails::FIELDS[$key??'']))$reported[$key]=$value??'';}$this->db->run('UPDATE external_records SET managed_fields=? WHERE connection_id=? AND record_id=?',[json_encode(array_values($template['fields']),JSON_THROW_ON_ERROR),$m['connection_id'],$record]);$service->setSourceDetails($a,$record,'action1',$reported,array_key_exists('comment',$device['values'])?($device['values']['comment']??''):null);$processed++;
   }
   $more=$page['next']!==null;$this->db->run('UPDATE action1_mappings SET sync_offset=?,status=?,processed_count=processed_count+?,skipped_count=skipped_count+?,last_error=NULL,last_sync=IF(?=1,last_sync,CURRENT_TIMESTAMP) WHERE id=?',[$page['next']??0,$more?'running':'complete',$processed,$skipped,$more?1:0,$id]);$this->db->run('UPDATE integration_connections SET status=?,sync_cursor=?,last_sync=IF(?=1,last_sync,CURRENT_TIMESTAMP) WHERE id=?',[$more?'syncing':'enabled',json_encode(['from'=>$page['next']]),$more?1:0,$m['connection_id']]);if(!$more)$this->audit->record($a,'integration.sync_completed','action1',$id,(int)$m['organization_id']);return ['more'=>$more,'processed'=>$processed,'skipped'=>$skipped,'message'=>$more?'Batch saved. Loading the next page.':'Sync complete. Missing devices were retained; archived configurations were not restored.'];
  });return $result;
 }catch(Action1Error $e){if($e->status!==429)$this->db->run("UPDATE action1_mappings SET status='error',last_error=? WHERE id=?",[$e->getMessage(),$id]);throw $e;}catch(HttpException $e){$this->db->run("UPDATE action1_mappings SET status='error',last_error='The local configuration template rejected this batch. Review required fields and retry.' WHERE id=?",[$id]);throw new Action1Error('The local configuration template rejected this batch. Review required fields and retry.',422);}
 });}
}
